cd /run/initramfs/cos-state/cOS; m=$(sed -n 's/.*mtime_ns=//p' active.img.sha256); b=$(dd if=active.img bs=1 skip=480000000 count=1 2>/dev/null | od -An -tu1 | tr -d ' '); n=$(( (b+1)%256 )); printf "$(printf '\\x%02x' $n)" | dd of=active.img bs=1 seek=480000000 conv=notrunc 2>&1 | tail -1; touch -d "@${m:0:10}.${m:10}" active.img; stat -c '%s %.9Y' active.img; cat active.img.sha256
